from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('L')
def crop(name, x1,y1,x2,y2, s=4, grid=50):
    c = im.crop((x1,y1,x2,y2)).convert('RGB')
    c = c.resize(((x2-x1)*s,(y2-y1)*s), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for x in range(0,x2-x1+1,grid):
        d.line([(x*s,0),(x*s,(y2-y1)*s)], fill=(255,0,0), width=1)
        if x: d.text((x*s+2,2), str(x1+x), fill=(255,255,0))
    for y in range(0,y2-y1+1,grid):
        d.line([(0,y*s),((x2-x1)*s,y*s)], fill=(255,0,0), width=1)
        if y: d.text((2,y*s+2), str(y1+y), fill=(0,255,255))
    c.save('crops/'+name)
